def parse_csv_line(line: str) -> list[str]:
    """Разобрать одну CSV-строку по заданным правилам RFC 4180."""
    if line.startswith("\ufeff"):
        line = line[1:]

    if line == "":
        return []

    fields: list[str] = []
    i = 0
    n = len(line)

    while True:
        if i < n and line[i] == '"':
            # Поле в двойных кавычках.
            i += 1
            chars: list[str] = []

            while True:
                if i >= n:
                    raise ValueError("unterminated quoted field")

                ch = line[i]

                if ch == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        chars.append('"')
                        i += 2
                    else:
                        i += 1
                        break
                else:
                    chars.append(ch)
                    i += 1

            if i < n and line[i] != ',':
                raise ValueError("unexpected character after closing quote")

            fields.append("".join(chars))

            if i == n:
                return fields

            # Пропускаем запятую после quoted-поля.
            i += 1
            if i == n:
                fields.append("")
                return fields
        else:
            # Незакавыченное поле: читаем до запятой или конца строки.
            start = i
            while i < n and line[i] != ',':
                i += 1

            fields.append(line[start:i])

            if i == n:
                return fields

            # Пропускаем запятую.
            i += 1
            if i == n:
                fields.append("")
                return fields

